from typing import Dict, List, Sequence, Tuple
from stockflow.first_fit_decreasing import first_fit_decreasing


def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be greater than 0")

    merged_skus: Dict[str, Tuple[int, int]] = {}
    for sku, qty, unit_weight in lines:
        if qty <= 0 or unit_weight <= 0:
            raise ValueError("Quantity and unit weight must be greater than 0")
        if sku in merged_skus:
            existing_qty, existing_weight = merged_skus[sku]
            if unit_weight != existing_weight:
                raise ValueError(f"SKU {sku} has inconsistent unit weights")
            merged_skus[sku] = (existing_qty + qty, unit_weight)
        else:
            merged_skus[sku] = (qty, unit_weight)

    items: List[Tuple[str, int]] = []
    item_id_to_info: Dict[str, Tuple[str, int]] = {}

    item_counter = 0
    for sku, (qty, unit_weight) in merged_skus.items():
        if unit_weight > max_parcel_grams:
            raise ValueError(f"Single unit of SKU {sku} is heavier than max_parcel_grams")

        total_weight = qty * unit_weight
        if total_weight <= max_parcel_grams:
            # Keep as one item
            item_id = f"{item_counter}"
            items.append((item_id, total_weight))
            item_id_to_info[item_id] = (sku, qty)
            item_counter += 1
        else:
            # Split into individual units
            for _ in range(qty):
                item_id = f"{item_counter}"
                items.append((item_id, unit_weight))
                item_id_to_info[item_id] = (sku, 1)
                item_counter += 1

    bins = first_fit_decreasing(items, max_parcel_grams)

    result: List[Dict[str, int]] = []
    for bin in bins:
        parcel: Dict[str, int] = {}
        for item_id, weight in bin:
            sku, qty = item_id_to_info[item_id]
            parcel[sku] = parcel.get(sku, 0) + qty
        result.append(parcel)

    return result"
    }
  }
}
