from typing import Iterable, Mapping, List
from stockflow.on_hand_by_location import on_hand_by_location
from stockflow.parse_location import parse_location

def validate_transfer(
    lines: Iterable[str],
    case_sizes: Mapping[str, int],
    sku: str,
    from_location: str,
    to_location: str,
    qty: int,
    day: int
) -> List[str]:
    problems = []

    if qty <= 0:
        problems.append("BAD_QTY")

    if from_location.upper() == to_location.upper():
        problems.append("SAME_LOCATION")

    if not parse_location(from_location):
        problems.append(f"Invalid from_location: {from_location}")
    if not parse_location(to_location):
        problems.append(f"Invalid to_location: {to_location}")

    case_size = case_sizes.get(sku)
    if case_size is None:
        problems.append(f"SKU {sku} not found in case_sizes")
    elif qty % case_size != 0:
        problems.append(f"Quantity {qty} is not a multiple of case size {case_size}")

    try:
        stock_map = on_hand_by_location(lines, case_sizes, as_of_day=day - 1)
        stock = stock_map.get((sku, from_location), 0)
        if stock < qty:
            problems.append(f"Insufficient stock in {from_location}: {stock} available, {qty} requested")
    except ValueError:
        # If the utility fails due to line format, we can't calculate stock
        pass

    return problems
"}}}
